select * from api.company;
select grantee, table_name, privilege_type from information_schema.role_table_grants where table_schema='api' order by 2,1;
select schemaname,tablename,policyname,roles,cmd,qual,with_check from pg_policies;
select relname, relrowsecurity, relforcerowsecurity, relkind from pg_class where relnamespace='api'::regnamespace;
select tgname, tgrelid::regclass from pg_trigger where not tgisinternal;

select * from api.status order by 1;
select proname, pg_get_functiondef(oid) from pg_proc where pronamespace in ('priv'::regnamespace) ;
select a.number,a.company_id,s.name,a.amount from api.application a join api.status s on s.id=a.status_id order by 1;
select conname, pg_get_constraintdef(oid) from pg_constraint where connamespace='api'::regnamespace;

alter table api.company add column if not exists ref_key uuid unique;
create table api.contract(
 id serial primary key,
 number text not null unique,
 application_id integer not null references api.application(id),
 amount numeric not null check (amount>0),
 signed_on date not null default current_date,
 status text not null default 'Проект' check (status in ('Проект','Подписан')));
create index on api.contract(application_id);
create function priv.check_contract() returns trigger language plpgsql security definer set search_path to 'api' as $$
begin
 if not exists (select 1 from api.application a join api.status s on s.id=a.status_id where a.id=NEW.application_id and s.name='Одобрена') then
  raise exception 'договор возможен только по одобренной заявке' using errcode='check_violation';
 end if;
 return NEW;
end $$;
create trigger check_contract before insert or update on api.contract for each row execute function priv.check_contract();
alter table api.contract enable row level security;
create policy admin_all on api.contract for all to fund_admin using (true) with check (true);
create policy lawyer_all on api.contract for all to lawyer using (true) with check (true);
create policy applicant_read on api.contract for select to applicant using (
 exists (select 1 from api.application a where a.id=application_id and a.company_id=priv.my_company()));
grant select,insert,update on api.contract to lawyer;
grant select,insert,update,delete on api.contract to fund_admin;
grant select on api.contract to applicant;
grant usage,select on sequence api.contract_id_seq to lawyer, fund_admin;
grant select on api.application, api.company to lawyer;
grant usage on schema api to lawyer;
create policy lawyer_read on api.application for select to lawyer using (true);
update api.app_user set role='lawyer' where login='lawyer1';
create view api.limit_balance with (security_invoker=false) as
select c.name as company, c.funding_limit, ap.approved, coalesce(ct.contracted,0) as contracted,
 c.funding_limit - coalesce(ct.contracted,0) as remaining
from api.company c
join (select a.company_id, sum(a.amount) approved from api.application a join api.status s on s.id=a.status_id where s.name='Одобрена' group by 1) ap on ap.company_id=c.id
left join (select a.company_id, sum(k.amount) contracted from api.contract k join api.application a on a.id=k.application_id group by 1) ct on ct.company_id=c.id;
revoke all on api.limit_balance from public;
grant select on api.limit_balance to fund_admin, lawyer;
